From 4bc37c8a262d14419e74dcf6eaace9bea7b7f73b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 16:46:56 +0100
Subject: [PATCH] applets/notes: add spell checking

The note's text area had no spell checking, unlike other text fields that
follow the system spell check setting. Misspelled words are now underlined
when that setting is on, with suggestions, Add to Dictionary and Ignore.

BUG: 510606
---
 applets/notes/qml/main.qml | 79 ++++++++++++++++++++++++++++++++++++++
 1 file changed, 79 insertions(+)

diff --git a/applets/notes/qml/main.qml b/applets/notes/qml/main.qml
index 63a6409ba..c8331029c 100644
--- a/applets/notes/qml/main.qml
+++ b/applets/notes/qml/main.qml
@@ -19,6 +19,7 @@ import org.kde.kirigami as Kirigami
 import org.kde.ksvg as KSvg
 import org.kde.plasma.components as PlasmaComponents3
 import org.kde.plasma.plasmoid
+import org.kde.sonnet as Sonnet

 PlasmoidItem {
     id: root
@@ -276,9 +277,28 @@ PlasmoidItem {
                         }
                     }

+                    Sonnet.Settings {
+                        id: spellcheckSettings
+                    }
+
+                    Instantiator {
+                        id: spellcheckHighlighterInstantiator
+                        active: spellcheckSettings.checkerEnabledByDefault
+
+                        Sonnet.SpellcheckHighlighter {
+                            active: true
+                            document: mainTextArea.textDocument
+                            cursorPosition: mainTextArea.cursorPosition
+                            selectionStart: mainTextArea.selectionStart
+                            selectionEnd: mainTextArea.selectionEnd
+                            misspelledColor: Kirigami.Theme.negativeTextColor
+                        }
+                    }
+
                     onPressed: event => {
                         if (event.button === Qt.RightButton) {
                             event.accepted = true;
+                            contextMenu.updateSpellcheck(positionAt(event.x, event.y));
                             contextMenu.popup();
                             forceActiveFocus();
                         }
@@ -301,6 +321,65 @@ PlasmoidItem {
                         popupType: QQC2.Menu.Window

                         readonly property bool shortcutsEnabled: contextMenu.visible
+                        readonly property Sonnet.SpellcheckHighlighter spellcheckHighlighter: spellcheckHighlighterInstantiator.object as Sonnet.SpellcheckHighlighter
+                        property int spellcheckPosition: -1
+                        property string misspelledWord
+                        property list<string> spellcheckSuggestions
+
+                        function updateSpellcheck(position) {
+                            misspelledWord = "";
+                            spellcheckSuggestions = [];
+                            const clickedSelection = mainTextArea.selectedText.length > 0
+                                && position >= mainTextArea.selectionStart && position <= mainTextArea.selectionEnd;
+                            if (!spellcheckHighlighter || clickedSelection) {
+                                return;
+                            }
+                            const suggestions = spellcheckHighlighter.suggestions(position);
+                            if (spellcheckHighlighter.wordIsMisspelled) {
+                                spellcheckPosition = position;
+                                spellcheckSuggestions = suggestions;
+                                misspelledWord = spellcheckHighlighter.wordUnderMouse;
+                            }
+                        }
+
+                        Instantiator {
+                            model: contextMenu.spellcheckSuggestions
+                            delegate: QQC2.MenuItem {
+                                required property string modelData
+                                text: modelData
+                                onTriggered: contextMenu.retFocus(() => contextMenu.spellcheckHighlighter.replaceWord(modelData, contextMenu.spellcheckPosition))
+                            }
+                            onObjectAdded: (index, object) => contextMenu.insertItem(index, object)
+                            onObjectRemoved: (index, object) => contextMenu.removeItem(object)
+                        }
+
+                        QQC2.MenuItem {
+                            visible: contextMenu.misspelledWord.length > 0 && contextMenu.spellcheckSuggestions.length === 0
+                            enabled: false
+                            text: i18nc("@action:inmenu %1 is a misspelled word", "No Suggestions for \"%1\"", contextMenu.misspelledWord)
+                        }
+
+                        QQC2.MenuSeparator {
+                            visible: contextMenu.misspelledWord.length > 0
+                        }
+
+                        QQC2.MenuItem {
+                            visible: contextMenu.misspelledWord.length > 0
+                            icon.name: "list-add"
+                            text: i18nc("@action:inmenu %1 is a misspelled word", "Add \"%1\" to Dictionary", contextMenu.misspelledWord)
+                            onTriggered: contextMenu.retFocus(() => contextMenu.spellcheckHighlighter.addWordToDictionary(contextMenu.misspelledWord))
+                        }
+
+                        QQC2.MenuItem {
+                            visible: contextMenu.misspelledWord.length > 0
+                            text: i18nc("@action:inmenu ignore a misspelled word", "Ignore")
+                            onTriggered: contextMenu.retFocus(() => contextMenu.spellcheckHighlighter.ignoreWord(contextMenu.misspelledWord))
+                        }
+
+                        QQC2.MenuSeparator {
+                            visible: contextMenu.misspelledWord.length > 0
+                        }
+
                         ShortcutMenuItem {
                             _sequence: StandardKey.Undo
                             _enabled: contextMenu.shortcutsEnabled && mainTextArea.canUndo
-- 
